"""Small standalone KPI table. No network, chart runtime, model or inference."""
from __future__ import annotations

from html import escape
import json
from pathlib import Path


STYLE = r"""
:root{color-scheme:light;--bg:#f3f5f8;--panel:#fff;--ink:#17283b;--muted:#627286;--line:#dce3eb;--brand:#235bd1;--good:#137c55;--good-bg:#eaf6ef;--bad:#ab433c;--bad-bg:#fdf0ed;--storm:#9b6515;--storm-bg:#fff5df;--prod:#edf3ff;--shadow:0 10px 35px #19304708}
:root[data-theme=dark]{color-scheme:dark;--bg:#101820;--panel:#18232f;--ink:#e8eff8;--muted:#a6b6c7;--line:#304153;--brand:#90b9ff;--good:#8cddb1;--good-bg:#173e32;--bad:#ffaea6;--bad-bg:#472d2c;--storm:#f8cc79;--storm-bg:#3a3224;--prod:#20344f;--shadow:none}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:1740px;margin:auto;padding:35px 30px 60px}header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}.eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;font-weight:750;color:var(--brand)}h1{font-size:42px;line-height:1.1;letter-spacing:-.04em;margin:10px 0}h2{font-size:19px;margin:0 0 16px}p{margin:8px 0}.muted{color:var(--muted)}button,select{font:inherit;background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:9px 13px}button{cursor:pointer}button:hover,select:hover{border-color:var(--brand)}button:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--brand);outline-offset:2px}.toolbar{display:flex;align-items:flex-end;flex-wrap:wrap;gap:18px;padding:21px 0}.control{display:grid;gap:5px}.control label{font-weight:650;font-size:12px;color:var(--muted)}.control select{min-width:180px}.support{display:flex;flex-wrap:wrap;gap:10px 28px;padding:15px 20px;background:var(--panel);border:1px solid var(--line);border-radius:12px;margin-bottom:18px}.support strong{font-size:18px}.support span{display:block;color:var(--muted);font-size:12px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:13px;box-shadow:var(--shadow);overflow:hidden;margin:18px 0}.panel-head{padding:19px 22px 12px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums;white-space:nowrap}th,td{text-align:right;padding:12px 13px;border-bottom:1px solid var(--line)}thead th{background:var(--panel);color:var(--muted);font-weight:600;font-size:11px;vertical-align:bottom}thead button{font:inherit;font-weight:700;padding:0;border:0;border-radius:0;background:transparent}th:first-child,td:first-child{text-align:left;min-width:265px;white-space:normal}td:first-child{max-width:335px}tr:last-child td{border-bottom:0}tbody tr:hover{outline:1px solid var(--line);outline-offset:-1px}.model-name{font-weight:700}.model-detail{font-size:11px;color:var(--muted);margin-top:3px}.prod{background:var(--prod)}.storm{background:var(--storm-bg)}.storm td{color:var(--storm)}.observed td{color:var(--muted)}.badge{display:inline-block;font-size:10px;border-radius:4px;padding:1px 5px;background:var(--line);color:var(--ink);margin-left:5px;vertical-align:middle}.good{color:var(--good);background:var(--good-bg)}.bad{color:var(--bad);background:var(--bad-bg)}.note{padding:12px 22px;color:var(--muted);font-size:12px;border-top:1px solid var(--line)}.definitions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;padding:22px}.definitions strong{display:block;margin-bottom:6px}.definitions p{color:var(--muted);font-size:12px}details{padding:20px 22px}summary{font-weight:650;cursor:pointer}details ul{padding-left:22px}a{color:var(--brand)}.empty{text-align:center;padding:45px;color:var(--muted)}footer{font-size:12px;color:var(--muted);margin-top:25px}.legend{display:flex;flex-wrap:wrap;gap:16px;padding:0 22px 18px;color:var(--muted);font-size:12px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px;background:var(--good)}.dot.bad-dot{background:var(--bad)}.hint{font-size:12px;color:var(--muted)}@media(max-width:850px){main{padding:20px 12px}h1{font-size:35px}.definitions{grid-template-columns:1fr;gap:8px}header{gap:10px}.control{flex:1}.control select{min-width:140px}.support{gap:10px 20px}}@media print{.toolbar,#theme-toggle{display:none}main{max-width:none;padding:0}.table-scroll{overflow:visible}table{font-size:9px}td,th{padding:6px}.panel{box-shadow:none}body{background:white;color:black}.definitions{display:block}}
"""


SCRIPT = r"""
const P=JSON.parse(document.getElementById('kpi-data').textContent),$=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite=x=>typeof x==='number'&&Number.isFinite(x),fmt=(v,d=2)=>finite(v)?v.toLocaleString('fr-FR',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const labels=Object.fromEntries(P.catalog.map(x=>[x.id,x]));
let sortKey='mae_eur_mwh',sortAscending=true;
const metrics=[['mae_eur_mwh','MAE horaire','€/MWh ↓'],['rmse_eur_mwh','RMSE horaire','€/MWh ↓'],['win_rate_hour_pct','Win rate · heures','% ↑'],['win_rate_day_mae_pct','Win rate · jours MAE','% ↑'],['mae_day_mean_price_eur_mwh','MAE prix moyen / jour','€/MWh ↓'],['win_rate_day_mean_price_pct','Win rate · jours prix moyen','% ↑'],['mean_price_eur_mwh','Prix moyen','€/MWh']];
function current(){return P.periods[$('period').value];}
function counts(row,key){const names={win_rate_hour_pct:'hour',win_rate_day_mae_pct:'day_mae',win_rate_day_mean_price_pct:'day_mean_price'},n=names[key];if(!n||row.model_id==='__storm__'||!finite(row[key]))return null;return {wins:row['wins_'+n],losses:row['losses_'+n],ties:row['ties_'+n],total:n==='hour'?row.n_hours:row.n_days};}
function valueCell(row,key,storm){let cls='',tip='';const c=counts(row,key);
 if(c){tip=`${c.wins} victoires · ${c.losses} défaites · ${c.ties} égalités / ${c.total}`;cls=c.wins>c.losses?'good':c.wins<c.losses?'bad':'';}
 else if(key!=='mean_price_eur_mwh'&&finite(row[key])&&finite(storm?.[key])&&!key.startsWith('win_')){const d=row[key]-storm[key];cls=d < -1e-9?'good':d > 1e-9?'bad':'';tip='Comparaison à Storm sur le même support';}
 return `<td class="${cls}" title="${esc(tip)}">${fmt(row[key])}${key.startsWith('win_')&&finite(row[key])?' %':''}</td>`;}
function renderEconomic(period,zone,models){
 const economic=period.economic,section=$('economic-section');section.hidden=!economic;
 if(!economic)return;
 const rows=economic.rows.filter(r=>r.zone===zone),byId=Object.fromEntries(rows.map(r=>[r.model_id,r])),storm=byId.__storm__;
 const fields=['pnl_net_eur','gain_vs_storm_eur','gain_vs_storm_per_potential_mwh'];
 const header='<thead><tr><th>Modèle / configuration</th><th>P&amp;L simulé net<br>EUR</th><th>Gain net vs Storm<br>EUR ↑</th><th>Gain net vs Storm<br>EUR / MWh potentiel ↑</th></tr></thead>';
 const body=models.map(m=>{const r=byId[m.model_id]||{},meta=labels[m.model_id]||{},prod=meta.kind==='production';return `<tr class="${prod?'prod':''}" data-model="${esc(m.model_id)}"><td><div class="model-name">${esc(meta.label||m.model_id)}${prod?'<span class="badge">PRODUCTION</span>':''}</div><div class="model-detail">${esc(meta.family)}</div></td>${fields.map((f,i)=>{const v=r[f],cls=i&&finite(v)?(v>1e-9?'good':v< -1e-9?'bad':''):'';return `<td class="${cls}">${fmt(v)}</td>`;}).join('')}</tr>`;});
 if(storm)body.push(`<tr class="storm" data-model="__storm__"><td><div class="model-name">Storm officiel</div><div class="model-detail">Même portefeuille et même règle de décision</div></td>${fields.map(f=>`<td>${fmt(storm[f])}</td>`).join('')}</tr>`);
 $('economic-table').innerHTML='<table>'+header+'<tbody>'+body.join('')+'</tbody></table>';
 const ref=rows.find(r=>r.model_id!=='__storm__')||storm||{};
 const audit=economic.audit||{},alloc=Object.entries(audit.zone_capacity_mw||{}).map(([z,mw])=>`${z} : ${fmt(mw,0)} MW`).join(' · ');
 $('economic-rules').textContent=`Portefeuille de référence : ${fmt(audit.portfolio_capacity_mw,0)} MW au total (${alloc}). Allocation fixe, jamais redistribuée. Prise de position si |forecast − référence| > ${fmt(audit.signal_hurdle_eur_mwh)} EUR/MWh ; coûts et slippage : ${fmt(audit.net_cost_eur_mwh)} EUR/MWh engagé. Même règle pour chaque alternative.`;
 $('economic-note').textContent=`${fmt(ref.n_country_hours,0)} heures-pays admissibles · ${fmt(ref.potential_energy_mwh,0)} MWh potentiels communs. Le gain/MWh utilise ce même volume potentiel pour tous les modèles, pas leurs volumes effectivement engagés. Aucun résultat n’est annualisé. Sans prise de position : P&L = 0 EUR.`;
 $('economic-audit').textContent=JSON.stringify({hypotheses:economic.audit,couverture:economic.coverage},null,2);
}
function render(){const period=current(),zone=$('country').value,family=$('family').value;
 const rows=period.rows.filter(r=>r.zone===zone),storm=rows.find(r=>r.model_id==='__storm__');
 let models=rows.filter(r=>r.model_id!=='__storm__'&&(family==='all'||labels[r.model_id]?.family===family||labels[r.model_id]?.kind==='production'));
 models.sort((a,b)=>{const ap=labels[a.model_id]?.kind==='production',bp=labels[b.model_id]?.kind==='production';if(ap!==bp)return ap?-1:1;const av=a[sortKey],bv=b[sortKey];if(!finite(av)||!finite(bv))return finite(av)?-1:finite(bv)?1:0;const d=(av-bv)*(sortAscending?1:-1);return d||a.model_id.localeCompare(b.model_id);});
 const ref=rows.find(r=>r.model_id!=='__storm__')||storm||{};
 $('window').textContent=`${period.period.start_day} → ${period.period.end_day}`;
 $('hours').textContent=fmt(ref.n_hours,0);$('days').textContent=fmt(ref.n_days,0);
 $('observed-price').textContent=fmt(ref.observed_mean_price_eur_mwh)+' €/MWh';
 $('period-note').textContent=`Fenêtre demandée : ${period.period.days} jours. ${zone==='ALL'?'CWE : pondération par heure-pays ; décisions journalières par jour-pays.':'Prix et erreurs calculés sur les mêmes heures physiques.'}`;
 const header='<thead><tr><th>Modèle / configuration</th>'+metrics.map(([k,l,u])=>`<th><button type="button" data-sort="${k}" title="Trier par ${esc(l)}">${esc(l)} ${sortKey===k?(sortAscending?'↑':'↓'):''}</button><br>${esc(u)}</th>`).join('')+'</tr></thead>';
 const body=models.map(row=>{const m=labels[row.model_id]||{},prod=m.kind==='production';return `<tr class="${prod?'prod':''}" data-model="${esc(row.model_id)}"><td><div class="model-name">${esc(m.label||row.model_id)}${prod?'<span class="badge">PRODUCTION</span>':''}</div><div class="model-detail">${esc(m.family)} · ${esc(m.decision||'')}</div></td>${metrics.map(([k])=>valueCell(row,k,storm)).join('')}</tr>`;});
 if(storm)body.push(`<tr class="storm" data-model="__storm__"><td><div class="model-name">Storm officiel</div><div class="model-detail">Référence · mêmes heures et journées</div></td>${metrics.map(([k])=>`<td>${k.startsWith('win_')?'—':fmt(storm[k])}</td>`).join('')}</tr>`);
 body.push(`<tr class="observed"><td><div class="model-name">Prix observé</div><div class="model-detail">Même support horaire commun</div></td>${metrics.map(([k])=>`<td>${k==='mean_price_eur_mwh'?fmt(ref.observed_mean_price_eur_mwh):'—'}</td>`).join('')}</tr>`);
 $('kpi-table').innerHTML='<table>'+header+'<tbody>'+body.join('')+'</tbody></table>';
 $('empty-state').hidden=Boolean(ref.n_hours);$('empty-state').textContent='Aucune heure commune exploitable sur cette sélection. Aucune valeur n’est remplacée par zéro.';
 $('support-note').textContent=`${fmt(ref.n_hours,0)} heures${zone==='ALL'?'‑pays':''} communes · ${fmt(ref.n_days,0)} journées${zone==='ALL'?'‑pays':''} complètes. Les journées incomplètes restent utilisables pour les métriques horaires, jamais pour les métriques journalières.`;
 const coverage=period.coverage[zone]||{};$('coverage-data').textContent=JSON.stringify(coverage,null,2);
 renderEconomic(period,zone,models);
 document.querySelectorAll('[data-sort]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.sort;if(sortKey===k)sortAscending=!sortAscending;else{sortKey=k;sortAscending=!k.startsWith('win_');}render();}));
}
function theme(value){document.documentElement.dataset.theme=value;$('theme-toggle').textContent=value==='dark'?'Mode jour':'Mode nuit';$('theme-toggle').setAttribute('aria-pressed',String(value==='dark'));try{localStorage.setItem('nyx-kpi-theme',value);}catch{}}
let saved='light';try{saved=localStorage.getItem('nyx-kpi-theme')||'light';}catch{}theme(saved==='dark'?'dark':'light');
$('theme-toggle').addEventListener('click',()=>theme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
['country','period','family'].forEach(id=>$(id).addEventListener('change',render));render();
"""


def render_kpi(payload: dict, output: Path) -> Path:
    """Write a fully standalone artifact; the caller restricts output paths."""
    if not payload.get("periods") or not payload.get("catalog"):
        raise ValueError("KPI requires a model catalog and computed periods.")
    encoded = json.dumps(payload, ensure_ascii=False, allow_nan=False, separators=(",", ":")).replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    countries = ''.join(f'<option value="{escape(z)}">{escape(z)}</option>' for z in payload["zones"])
    periods = ''.join(f'<option value="{escape(key)}">{escape(key)} derniers jours</option>' for key in payload["periods"])
    families = ''.join(f'<option value="{escape(f)}">{escape(f)}</option>' for f in dict.fromkeys(x["family"] for x in payload["catalog"]))
    sources = ''.join('<li><strong>'+escape(m["label"])+"</strong> — "+escape(str(m.get("source_path", "")))+'</li>' for m in payload["catalog"])
    generated = escape(payload["generated_at_local"])
    source_day = escape(payload.get("source_delivery_day", "—"))
    document = f'''<!doctype html><html lang="fr" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KPI — NYX et derniers modèles</title><style>{STYLE}</style></head><body><main>
<header><div><div class="eyebrow">NYX · comparaison des modèles</div><h1>KPI</h1><p class="muted">Les dernières configurations, une période commune, les mêmes observations et le même Storm.</p></div><button id="theme-toggle" type="button" aria-pressed="false">Mode nuit</button></header>
<div class="toolbar"><div class="control"><label for="country">Pays</label><select id="country"><option value="ALL">CWE · agrégé</option>{countries}</select></div><div class="control"><label for="period">Période</label><select id="period">{periods}</select></div><div class="control"><label for="family">Famille affichée</label><select id="family"><option value="all">Tous les modèles</option>{families}</select></div><div class="hint">Masquer une famille ne change pas le support commun.<br>Cliquer sur un en-tête pour trier ; NYX reste épinglé.</div></div>
<div class="support"><div><strong id="window"></strong><span>Période sélectionnée</span></div><div><strong id="hours"></strong><span>Heures communes</span></div><div><strong id="days"></strong><span>Journées complètes</span></div><div><strong id="observed-price"></strong><span>Prix moyen observé</span></div></div><p id="period-note" class="hint"></p>
<section class="panel"><div class="panel-head"><h2>Comparaison des KPI</h2><p class="hint">MAE et RMSE : plus bas = mieux. Prix moyens en EUR/MWh. La valeur économique simulée est présentée séparément ci-dessous.</p></div><div id="kpi-table" class="table-scroll"></div><div id="empty-state" class="empty" hidden></div><div id="support-note" class="note"></div><div class="legend"><span><i class="dot"></i>Erreur inférieure à Storm / davantage de victoires que de défaites</span><span><i class="dot bad-dot"></i>Erreur supérieure à Storm / davantage de défaites</span><span>Les égalités ne sont pas des victoires. Survoler un win rate pour les effectifs.</span></div></section>
<section class="panel" id="economic-section"><div class="panel-head"><h2>Gain économique simulé · diagnostic EVA</h2><p>Référence : prix day-ahead observé de la veille, <strong>non négociable au cutoff de 08 h</strong>. Ces montants ne sont pas un P&amp;L réalisable ni une preuve de rentabilité.</p><p id="economic-rules" class="hint"></p></div><div id="economic-table" class="table-scroll"></div><div id="economic-note" class="note"></div><details><summary>Hypothèses économiques et couverture</summary><p>Pour chaque modèle et pour Storm : position selon le signe de l’écart à la référence, sous réserve du seuil, puis P&amp;L = position × (observé − référence) − coûts. Une référence absente ou ambiguë lors du changement d’heure exclut l’heure pour tous. Le support économique peut donc être plus restreint que celui des erreurs de prix.</p><p>Les hypothèses de publication de la référence ne constituent pas une certification point-in-time. Les paramètres sont repris du laboratoire EVA existant, sans les optimiser sur cette période.</p><pre id="economic-audit"></pre></details></section>
<section class="panel"><div class="definitions"><div><strong>Win rate · heures</strong><p>Part des heures où l’erreur absolue du modèle est strictement inférieure à celle de Storm. Toutes les heures communes, égalités incluses, restent au dénominateur.</p></div><div><strong>Win rate · jours MAE</strong><p>Part des journées complètes où la moyenne des erreurs absolues horaires du modèle est inférieure à celle de Storm. Une journée vaut une décision, même lorsqu’elle compte 23 ou 25 heures.</p></div><div><strong>Win rate · jours prix moyen</strong><p>Part des journées complètes où le prix moyen prévu par le modèle est plus proche du prix moyen observé que celui de Storm. La MAE du prix moyen mesure cette erreur quotidienne en EUR/MWh.</p></div></div></section>
<section class="panel"><details><summary>Périmètre, comparabilité et sources</summary><p>Historique du modèle en production : <strong>NYX nucléaire + Kalman</strong>, figé dans les sources de livraison du {source_day}. Les lignes expérimentales ne sont pas déployées. Les lignes « intervalles recalibrés » gardent les mêmes prix : leurs KPI ponctuels sont donc identiques.</p><p>Les sources ont déjà servi à l’exploration. Ce tableau est descriptif, pas une validation indépendante ni une sélection automatique du meilleur modèle. Les replis vers NYX sont conservés. Les lignes live sont exclues, même déjà observées.</p><p>Prix moyen affiché : moyenne sur les mêmes heures physiques appariées. Les métriques journalières utilisent uniquement les jours complets sur ces mêmes modèles. Aucune interpolation, aucun prix absent remplacé par zéro. Égalité : tolérance absolue de 10⁻⁹ EUR/MWh.</p><p>Lecture locale uniquement : aucun entraînement, forecast, appel API ou changement à Forecast.ps1.</p><h3>Sources des configurations</h3><ul>{sources}</ul><h3>Couverture de la sélection</h3><pre id="coverage-data"></pre></details></section>
<footer>Généré le {generated} · <a href="kpi_metrics.json">Données KPI</a> · <a href="source_audit.json">Audit des sources</a> · <a href="report_manifest.json">Empreintes du rapport</a></footer>
</main><script id="kpi-data" type="application/json">{encoded}</script><script>{SCRIPT}</script></body></html>'''
    output = Path(output)
    with output.open("x", encoding="utf-8") as stream:
        stream.write(document)
    return output
